(1744, 0, 2, 'FM Leased', 'Partial', 'B.1', 'Review of Fire Safety System', 'Is Fire Hydrant System installed in the facility ?', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"Fire Hydrant system is not installed in the warehouse\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"1. Legal Issue may occur\\n2. In case of major fire, the warehouse staff\\/Fire department team may find difficulty in extinguishing the fire\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Fire Hydrant system should be installed in the warehouse as per NBC norms\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Fire Hydrant\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"144\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
(1745, 0, 2, 'FM Leased', 'Partial', 'B.2', 'Review of Fire Safety System', 'Is pressure in the hydrant system maintained in between 6 Kg/cm', '{\"findings\":{\"text\":\"Findings (FM Leased - )\",\"yes\":\"\",\"no\":\"Pressure in the fire hydrant system not maintained b/w  6 Kg/cm² to 8 Kg/cm²\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"If there is low pressure in the fire hydrant line, it may be difficult to target the fire at longer distance\",\"na\":\"\"},\"actions\":{\"text\":\"Actions/Recommendation\",\"yes\":\"\",\"no\":\"Water pressure in the fire hydrant line should remain in between 6 Kg/cm² to 8 Kg/cm²\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Fire Hydrant\",\"na\":\"\"},\"ua_uc\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"color_code\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Combined Risk Rating\",\"yes\":\"\",\"no\":\"16\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', '2026-04-09 11:54:39'),
