(2340, 0, 2, 'Office', 'GSC', 'C.2', 'Review of Personal Protective Equipment', 'All personnel are using Safety Harnesses for Working at height.? ( Applicable For VNA/Order Picker Operation.)', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"Safety Harnesses are not used for working at height.(  Applicable For VNA\\/Order Picker Operation )\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Personal injury\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Safety harness should be used for working at height.\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"PPE\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operational Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"48\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
