(2673, 0, 2, 'Office', 'Project Forwarding', 'F.11', 'Review of MHE Operation and Maintenance', 'Is safe distance maintained between the two MHEs?', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"Safe distance not maintained b\\/w the two MHEs\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"The operator will not be able to safe guard the machine if it is required to apply the emergency breaks\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Safe distance should be maintained between the two MHEs\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Forklift\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operational Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"48\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
(2674, 0, 2, 'Office', 'Project Forwarding', 'F.12', 'Review of MHE Operation and Maintenance', 'Is MHEs key register maintained ?', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"Key register for MHE is not maintained\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Security may issue the key to the unauthorize person which may result in major incident\\/accident\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Key issue register for all MHE should be prepared and key should be issued only to the authorized person\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Key Register\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operational Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"9\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
