(3167, 0, 2, '4PL', '4PL', 'B.2', 'Review of Fire Safety System', 'Is pressure in the hydrant system maintained in between 6 Kg/cm', '{\"findings\":{\"text\":\"Findings (4PL - )\",\"yes\":\"\",\"no\":\"Pressure in the fire hydrant system not maintained b\\/w  6 Kg\\/cm² to 8 Kg\\/cm²\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"If there is low pressure in the fire hydrant line, it may be difficult to target the fire at longer distance\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Water pressure in the fire hydrant line should remain in between 6 Kg\\/cm² to 8 Kg\\/cm²\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Fire Hydrant\",\"na\":\"\"},\"ua_uc\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"color_code\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Combined Risk Rating\",\"yes\":\"\",\"no\":\"16\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', '2026-04-09 11:59:10'),
