(3263, 0, 2, '4PL', '4PL', 'H.1', 'Review of Electrical Safety', 'Is SLD prepared and updated available ?', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"SLD is not available for the warehouse\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Electrician will not be able to identify the route of faulty wire\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"SLD should be prepared and followed strictly for any electrical maintenance\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"SLD\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Others\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"8\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
