(3295, 0, 2, '4PL', '4PL', 'I.4', 'Review of Management of Dangerous Goods (DG) / Hazardous Material', 'Are chemicals stored in the facility are as per the compatibility matrix and displayed at prominent location ?', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"Chemicals in the warehouse is not stored as per the compatibility matrix and it not displayed\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Staff may store incompatible material together. If not displayed, there are chances of error that incompatible chemical can be stored together\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"All chemicals should be stored as per the compatibility matrix and it should be displayed.\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Storage Method\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operational Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"27\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
(3296, 0, 2, '4PL', '4PL', 'I.5', 'Review of Management of Dangerous Goods (DG) / Hazardous Material', 'Is Eye Wash facility or safety shower installed in the facility at prominent location as per the risk assessment ? If required', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"Eye wash facility and safety shower is not available in the warehouse\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"If any chemical splashes on someone, it will be difficult to wash the entire body and eyes with the help of water\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Eye wash facility and safety shower should be installed in the warehouse at prominent location as per the risk assessment\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Eye Washer\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"48\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
(3297, 0, 2, '4PL', '4PL', 'I.6', 'Review of Management of Dangerous Goods (DG) / Hazardous Material', 'Is it confirmed that there is no obstruction to the emergency eye wash/ eye shower ?', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"There is obstruction observed in the way of emergency shower \\/ eye washer\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"In case of any emergency, person may find difficulty in reaching to the eye wash\\/eye shower\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"There should not be any obstruction to the eye wash\\/eye shower\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Storage Method\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operational Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"8\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
