(3535, 0, 2, 'Distribution Ac-Warehousing & Delivery', 'Part Load', 'G.1', 'Review of Dock Safety', 'Once vehicle lined up to the dock area , vehicle engine should be turned off and vehicle keys should be handover to security / dock person by driver', '{\"findings\":{\"text\":\"Findings (Distribution Ac-Warehousing & Delivery - )\",\"yes\":\"\",\"no\":\"Once vehicle is lined up to the dock area , vehicle engine is not turned off and vehicle keys are not handed  over to the security \\/ dock person by driver and driver should is not sitting in the vehicle\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Not only a major accident even fatality may occur if dock safety rules are not followed\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Once vehicle lined up to the dock area , vehicle engine should be turned off and vehicle keys should be handover to security \\/ dock person by driver and driver should not sit in the vehicle\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Process\",\"na\":\"\"},\"ua_uc\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Very High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"color_code\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"Operatiol Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Combined Risk Rating\",\"yes\":\"\",\"no\":\"45\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', '2026-04-09 11:59:55'),
(3536, 0, 2, 'Distribution Ac-Warehousing & Delivery', 'Part Load', 'G.2', 'Review of Dock Safety', 'Is wheel chocks available and used at the time of loading/unloading process ?', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"Wheel chocks not used at the time of loading\\/unloading process\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Major incident\\/accident may occur\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Wheel chocks should be used at the time of loading\\/off-loading\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Wheel Chock\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Very High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operational Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"60\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
(3537, 0, 2, 'Distribution Ac-Warehousing & Delivery', 'Part Load', 'G.3', 'Review of Dock Safety', 'Is speed limit of 15Km/Hr mentioned outside the facility ?', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"Speed limit is not mentioned outside the warehouse\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Major accident or even fatality may occur if someone crosses the speed limit\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Speed limit should be mentioned in the warehouse at multiple location and should be strictly followed\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Display Board\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"96\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
