(3669, 0, 2, 'Distribution Ac-Warehousing & Delivery', 'Part Load', 'T.4', 'Review of Copacking Safety', 'Are only hand pallet trucks or electric pallet stackers used in the conveyor / production areas (no forklifts, no reach trucks) ?', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"Forklifts and reach trucks are used in conveyor\\/production areas\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Major\\/minor incident can happen as there are personal working in the area\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Only hand pallet trucks or electric pallet stackers should be used in the conveyor \\/ production areas (no forklifts, no reach trucks)\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Safety\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operational Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"6\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
