(3801, 0, 2, 'Distribution Ac-FTL', 'FTL', 'F.2', 'Review of MHE Operation and Maintenance', 'Are MHEs safety devices like safety belt, horn, reverse horn, front light, rear light, beacon light, Blue light and emergency stop are in good condition and working ? if applicable', '{\"findings\":{\"text\":\"Findings (Client Leased - NA)\",\"yes\":\"\",\"no\":\"MHEs safety devices like safety belt,  horn, reverse horn, front light, rear light, beacon light, Blue light and emergency stop are not in good condition and working .\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Major\\/minor MHE related incident occurred if any safety devices are not in functional\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"MHEs safety devices should be in good condition and working.\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"MHE\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"96\",\"na\":\"\"}}', '', NULL, 1, '0000-00-00 00:00:00', NULL),
