(4364, 0, 3, 'Client Leased', 'External Warehouse', 'E.16', 'Review of Material Stacking and Handling', 'Toe guard for the mezzanine & MTS', '{\"findings\":{\"text\":\"Findings (Client Leased - )\",\"yes\":\"\",\"no\":\"Toe guard for the mezzanine & MTS not Installed\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Risk of materials\\/tools falling from height, leading to injury to personnel below\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Install proper toe guards (minimum ~100\\u2013150 mm height) along all exposed edges of mezzanine and MTS platforms\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Mezzanine Gaurds\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"144\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(4365, 0, 3, 'Client Leased', 'External Warehouse', 'E.17', 'Review of Material Stacking and Handling', 'Smoke detectors in MTS', '{\"findings\":{\"text\":\"Findings (Client Leased - )\",\"yes\":\"\",\"no\":\"Smoke detectors in MTS not installed\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Delay in early fire detection leading to rapid fire spread\\n- Increased risk to life and property due to late alarm activation\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Install approved smoke detectors in MTS area as per fire safety design\\n- Integrate with main fire alarm panel for early warning\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"FIre Alaram\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"144\",\"na\":\"\"}}', '', 'Smoke detector', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
