(4372, 0, 3, 'Client Leased', 'External Warehouse', 'F.1', 'Review of MHE Operation and Maintenance', 'Is daily/Weekly/Monthly inspection checklist maintained and records of the same are available ?', '{\"findings\":{\"text\":\"Findings (Client Leased - )\",\"yes\":\"\",\"no\":\"Daily\\/Weekly\\/Monthly inspection checklist is not maintained and recorded\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Defective observation in the MHE may got missed if inspection checklist is not maintained\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Daily\\/Weekly\\/Monthly inspection checklist should be maintained\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Checklist\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operatiol Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"16\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(4373, 0, 3, 'Client Leased', 'External Warehouse', 'F.2', 'Review of MHE Operation and Maintenance', 'Are MHE\'s safety devices like safety belt, horn, reverse horn, front light, rear light, beacon light, Blue light and emergency stop are in good condition and working ? if applicable', '{\"findings\":{\"text\":\"Findings (Client Leased - )\",\"yes\":\"\",\"no\":\"MHE\'s safety devices like safety belt,  horn, reverse horn, front light, rear light, beacon light, Blue light and emergency stop are not in good condition and working .\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Major\\/minor MHE related incident occurred if any safety devices are not in functional\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"MHE\'s safety devices should be in good condition and working.\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"MHE\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"96\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
