(4726, 0, 3, 'Client Leased', 'Inplant', 'I.8', 'Review of Management of Dangerous Goods (DG) / Hazardous Material', 'Are Fire extinguishers installed near to the hazardous material areas as per the requirement', '{\"findings\":{\"text\":\"Findings (Client Leased - )\",\"yes\":\"\",\"no\":\"Adequate no. of FE\'s are not installed near to the Hazardous material storage area\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"In case of small fire, person will not be able to extinguish the fire and that small fire may turn into big fire\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Adequate number of fire extinguisher should be installed near to the hazardous material storage area\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Fire Extinguishers\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"54\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(4727, 0, 3, 'Client Leased', 'Inplant', 'I.9', 'Review of Management of Dangerous Goods (DG) / Hazardous Material', 'Is the Compressed gas cylinder stored in a Upright position and secure with the chain? If applicable', '{\"findings\":{\"text\":\"Findings (Client Leased - )\",\"yes\":\"\",\"no\":\"Compressed gas cylinder are not stored in a Upright position and secure with the chain.\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"If Compresses gas cylinder are not store in upright direction and  explode it may travel to any direction.\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Compressed gas cylinder should be  stored in a Upright position and secure with the chain.\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Compressed Gas Cylinder\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"48\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
