(5806, 0, 3, 'FM Leased', 'MCF', 'E.8', 'Review of Material Stacking and Handling', 'Are uprights in the HDR is observed in good condition without any evidence of dents ?', '{\"findings\":{\"text\":\"Findings (FM Leased - )\",\"yes\":\"\",\"no\":\"Upright in the HDR are not in good condition\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"There are chances that the structure may collapse\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"All uprights should remain in good condition\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Uprights\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"96\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(5807, 0, 3, 'FM Leased', 'MCF', 'E.9', 'Review of Material Stacking and Handling', 'Are bracings in the HDR is in good condition without any damage ?', '{\"findings\":{\"text\":\"Findings (FM Leased - )\",\"yes\":\"\",\"no\":\"Bracings in the rack are not in good condition\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Dented bracings result in decreasing the strength of the HDR system\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"All bracings in the HDR should remain in good condition\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Bracings\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"32\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(5808, 0, 3, 'FM Leased', 'MCF', 'E.10', 'Review of Material Stacking and Handling', 'Are upright connectors installed ?', '{\"findings\":{\"text\":\"Findings (FM Leased - )\",\"yes\":\"\",\"no\":\"Upright connectors are not installed as per the requirement\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Collapse of the structure\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Upright connectors must be installed for the rack system, as upright connectors provide strength to every other upright\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Upright Connectors\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"144\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(5809, 0, 3, 'FM Leased', 'MCF', 'E.11', 'Review of Material Stacking and Handling', 'Are proper foundation bolts (grouting) provided for the uprights ?', '{\"findings\":{\"text\":\"Findings (FM Leased - )\",\"yes\":\"\",\"no\":\"Grouting of the uprights are not adequate\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Collapse of the structure\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Grouting of the upright should be adequate\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Uprights\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Very High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Very High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"225\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(5810, 0, 3, 'FM Leased', 'MCF', 'E.12', 'Review of Material Stacking and Handling', 'Are safety pins installed in the HDR setup ?', '{\"findings\":{\"text\":\"Findings (FM Leased - )\",\"yes\":\"\",\"no\":\"Safety pins are found missing in the HDR\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"The load beam may get removed\\/dislocated easily\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Safety pins should be provided for 100% of the locations in the racking system\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Safety Pins\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"32\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(5811, 0, 3, 'FM Leased', 'MCF', 'E.13', 'Review of Material Stacking and Handling', 'Is rear support for the pallets provided in the HDR ?', '{\"findings\":{\"text\":\"Findings (FM Leased - )\",\"yes\":\"\",\"no\":\"Rear support to the pallets not provided in the HDR\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Pallet may not be placed properly and material or pallet may get disbalanced and may fall\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Rear support to the pallet should be provided for all pallet position at G+1 level and above\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Rear Support\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"48\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
