(6405, 0, 3, 'Office', '4PL', 'F.4', 'Review of MHE Operation and Maintenance', 'Whether dedicated complaint register maintained ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Dedicated Complaint register is not available\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"It will be difficult to track the defective observation in the machines and take necessary corrective action\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Dedicated Complaint register should be maintained\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Records\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operatiol Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"9\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(6406, 0, 3, 'Office', '4PL', 'F.5', 'Review of MHE Operation and Maintenance', 'Have MHE drivers gone through any internal training ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Internal training to the MHE drivers is not provided\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Major incident\\/accident may occur if training is not provided to the operators\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Internal Training to the MHE operators should be provided on a regular interval of time\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Training\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operatiol Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"27\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(6407, 0, 3, 'Office', '4PL', 'F.6', 'Review of MHE Operation and Maintenance', 'Have MHE drivers gone through any external training by OEM at least once in 6 months ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"MHE drivers not gone through any external training by OEM at least once in 6 months\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Major incident\\/accident may occur if training is not provided to the operators\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"MHE drivers should go through any external training by OEM at least once in 6 months\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Training\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"54\",\"na\":\"\"}}', '', 'Since training is requiring cost, the point is defined as Opex', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(6408, 0, 3, 'Office', '4PL', 'F.7', 'Review of MHE Operation and Maintenance', 'Are name of person authorize to drive MHE displayed at the prominent location ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Name of Authorized MHE drivers is not displayed at prominent location in the warehouse\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Unauthorize person may try to drive the MHE and which may further result in some major incident\\/accident\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Name of authorized person to operate MHE must be displayed in the warehouse\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Display Board\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"96\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
