(6410, 0, 3, 'Office', '4PL', 'F.9', 'Review of MHE Operation and Maintenance', 'Is MHEs key register maintained ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Key register for MHE is not maintained\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Security may issue the key to the unauthorize person which may result in major incident\\/accident\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Key issue register for all MHE should be prepared and key should be issued only to the authorized person\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Key Register\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operatiol Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"9\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(6411, 0, 3, 'Office', '4PL', 'F.10', 'Review of MHE Operation and Maintenance', 'Is Safe Working load on each MHE displayed ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"SWL is not displayed on MHE\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Person may lift heavy load from the MHE, which  may result in the major accident\\/topple of MHE\\/Damage of material\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"SWL should be displayed on the MHE\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"SWL\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"96\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(6412, 0, 3, 'Office', '4PL', 'F.11', 'Review of MHE Operation and Maintenance', 'Is Speed limit mentioned in the facility ? (5 Km/Hr inside warehouse) and followed by the Operators?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Speed limit not mentioned in the warehouse and not followed by the Operator\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Major accident or even fatality may occur if someone crosses the speed limit\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Speed limit should be mentioned in the warehouse at multiple location and should be strictly followed\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Display Board\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"96\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
