(6683, 0, 3, 'Office', 'GSC', 'E.15', 'Review of Material Stacking and Handling', 'Is the MTS Sliding gate is properly fixed and  in good condition? If applicable', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"MTS Sliding gate is not properly fixed and  not in good condition\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"MTS Sliding get may fell down\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"MTS Sliding gate should be properly fixed and in good condition.\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Sliding Gate\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"48\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(6684, 0, 3, 'Office', 'GSC', 'E.16', 'Review of Material Stacking and Handling', 'Toe guard for the mezzanine & MTS', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Toe guard for the mezzanine & MTS not Installed\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Risk of materials\\/tools falling from height, leading to injury to personnel below\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Install proper toe guards (minimum ~100\\u2013150 mm height) along all exposed edges of mezzanine and MTS platforms\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Mezzanine Gaurds\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"144\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(6685, 0, 3, 'Office', 'GSC', 'E.17', 'Review of Material Stacking and Handling', 'Smoke detectors in MTS', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Smoke detectors in MTS not installed\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Delay in early fire detection leading to rapid fire spread\\n- Increased risk to life and property due to late alarm activation\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Install approved smoke detectors in MTS area as per fire safety design\\n- Integrate with main fire alarm panel for early warning\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"FIre Alaram\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"144\",\"na\":\"\"}}', '', 'Smoke detector', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(6686, 0, 3, 'Office', 'GSC', 'E.18', 'Review of Material Stacking and Handling', 'Is slotted angle racks installed in the facility and is in good condition ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Slotted angle racks are not in good condition\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"The material may from the damaged Slotted angle racks\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"All damaged racks should either be repaired or replaced with the new good racks\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Maintenance\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"24\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(6687, 0, 3, 'Office', 'GSC', 'E.19', 'Review of Material Stacking and Handling', 'Cargos are properly stacked, secured and shrink wrapped to avoid tripping and falling (at upper racks) ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Cargos are not properly stacked and shrink wrapped\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"There are chances that the material stored at G+1 level and above may fall and result in damage of material or personal injury\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"All cargos stored at or above G+1 level should be shrink wrapped\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Shrink Wrap\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"96\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(6688, 0, 3, 'Office', 'GSC', 'E.20', 'Review of Material Stacking and Handling', 'Are pallets used for stacking of material are not damaged and are in good condition ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Pallets found in damage condition\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Broken pallet may result in damage of the material while lifting and may also result in personal injury\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"All broken pallets should be replaced with the good pallets\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Storage Practices\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operatiol Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"48\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(6689, 0, 3, 'Office', 'GSC', 'E.21', 'Review of Material Stacking and Handling', 'Stacking of material near electrical panels, battery charging stations?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"material is stacked  near electrical panels, battery charging stations\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"- Increased fire risk due to presence of combustible materials near electrical sources\\n- Risk of short circuit, overheating, or sparks igniting nearby materials\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Maintain minimum clearance (at least 1 meter) around electrical panels and charging stations\\n- Remove all combustible and non-essential materials from the area\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":null,\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":null,\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":null,\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":null,\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":null,\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":null,\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":null,\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
