(7010, 0, 3, 'Office', 'Project Forwarding', 'H.1', 'Review of Electrical Safety', 'Is SLD prepared and updated available ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"SLD is not available for the warehouse\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Electrician will not be able to identify the route of faulty wire\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"SLD should be prepared and followed strictly for any electrical maintenance\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"SLD\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Others\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"8\",\"na\":\"\"}}', '', 'SLD - Single Line Diagram', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(7011, 0, 3, 'Office', 'Project Forwarding', 'H.2', 'Review of Electrical Safety', 'Are the electrical installations inspected and repaired by the authorized PWD licensed electrician only ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Electrical installations not inspected and not repaired by the authorized PWD licensed electrician only\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Inappropriate selection and installation of electrical equipment by untrained electrician may lead to major hazard\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Electrical installations should be inspected and should be repaired by the authorized PWD licensed electrician only\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Maintenance\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"32\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(7012, 0, 3, 'Office', 'Project Forwarding', 'H.3', 'Review of Electrical Safety', 'Are electrical rubber mats conforming to IS 15652 kept under each panel boards ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Electrical rubber mats conforming to IS 15652 not kept under each panel boards\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Electrical shock to the personal operating electrical panel\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Electrical rubber mats conforming to IS 15652 should be kept under each panel boards\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Rubber Mats\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Very High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"135\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46');
INSERT INTO `alert_audit_questions` (`question_id`, `group_id`, `audit_template_id`, `audit_site_category_name`, `audit_sub_category_name`, `audit_category_id`, `audit_category`, `audit_question`, `capa_json`, `audit_question_default_value`, `note`, `status`, `default_date`, `update_date`) VALUES
(7013, 0, 3, 'Office', 'Project Forwarding', 'H.4', 'Review of Electrical Safety', 'Is proper earthing network maintained and earthing provided to all Panel DBs etc.?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Proper earthing network not maintained and Earthing is not provided to all DBs\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Electrocution may occur\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"A proper earthing network should be maintained and earthing should be provided to all DBs.\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Earthing\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Very High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"180\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(7014, 0, 3, 'Office', 'Project Forwarding', 'H.5', 'Review of Electrical Safety', 'Is proper rated ELCBs/RCCBs are installed at various locations ? And are checked once in 6 month?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Proper rated ELCBs\\/RCCBs are not installed at various locations.\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"An Earth-leakage circuit breaker (ELCB) is a safety device used in electrical installations with high earth impedance to prevent shock. It detects small stray voltages on the metal enclosures of electrical equipment and interrupts the circuit if the voltage level exceeds danger threshold. RCD, Residual-Current Device or RCCB, Residual Circuit Current Breaker. It is an electrical wiring device whose function is to disconnect the circuit when it detects currents leaking to the earth wire. It also gives protection against electric shock or electrocution caused by direct contacts\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Proper rated ELCBs\\/RCCBs should be installed at various location and should be check once in a 6 month\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"ELCB\\/RCCB\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"144\",\"na\":\"\"}}', '', 'If MCB is there, then also point can be closed as it serves the purpose of auto-tripping in case of voltage surge', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(7015, 0, 3, 'Office', 'Project Forwarding', 'H.6', 'Review of Electrical Safety', 'Are the cable above ground supported with proper clamps and conduits/cable tray?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Cable above ground are not supported with proper clamps and conduits\\/cable tray\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Rodents may damage the wire\\/Person injury due to trip hazard\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"All cable in the warehouse should be supported with proper clamps and conduits\\/cable tray\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Cable Dressing\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Capex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"108\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(7016, 0, 3, 'Office', 'Project Forwarding', 'H.7', 'Review of Electrical Safety', 'Is the hole made for cable entry on panel or wall is sealed properly ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Hole made for cable entry on panel or wall is not sealed properly\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"If there is a fire on any one side, there are chances that the fire may spread on both the sides, snakes & rodents may come inside Warehouse from this hole\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Hole made for cable entry on panel or wall should be sealed properly\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Maintenance\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"12\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(7017, 0, 3, 'Office', 'Project Forwarding', 'H.8', 'Review of Electrical Safety', 'Is the cable gland provided in electrical equipment and panels?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Cable glands are not provided in electrical equipment and panels.\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"There are chances  rodents\\/lizard may enter inside the panel and Short circuit may occur\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":null,\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Cable Glands\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Low\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Yellow\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"12\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
(7018, 0, 3, 'Office', 'Project Forwarding', 'H.9', 'Review of Electrical Safety', 'Is danger notice/signage displayed at all prominent locations as like transformer area/DG area/Electrical panels ?', '{\"findings\":{\"text\":\"Findings (Office - )\",\"yes\":\"\",\"no\":\"Danger notice signage is not displayed near to the high voltage area\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Life risk of a person not aware about the risk associated with the same\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Danger notice\\/signage should be displayed at all prominent locations as like transformer area\\/DG area\\/Electrical panels\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Display Board\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"Medium\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Opex\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"72\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
