(7999, 0, 3, 'Distribution Ac-Warehousing & Delivery', 'Part Load', 'T.1', 'Review of Copacking Safety', 'Are all conveyor / production line collaborators working with no loose clothes, no accessories (jewels) and do they tie back their hair ?', '{\"findings\":{\"text\":\"Findings (Distribution Ac-Warehousing & Delivery - )\",\"yes\":\"\",\"no\":\"All conveyor \\/ production line collaborators working with loose clothes, accessories (jewels) and they do not tie back their hair\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Manor\\/minor incident because of the moving parts\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"All conveyor \\/ production line collaborators should not work with loose clothes, accessories (jewels) and they should tie back their hair\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Safety\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operatiol Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"48\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
