(8572, 0, 3, '4PL - Headcount', '4PL', 'R.10', 'Review of MHE Operation and Maintenance', 'Do MHE drivers maintain a safe distance from other employees (when inserting / removing pallets, the radius of the mast height including the load) ?', '{\"findings\":{\"text\":\"Findings (4PL - Headcount - )\",\"yes\":\"\",\"no\":\"MHE  drivers do not maintain a safe distance from other employees (when inserting \\/ removing pallets, the radius of the mast height including the load)\",\"na\":\"\"},\"risk\":{\"text\":\"Risk\",\"yes\":\"\",\"no\":\"Risk of Accident\",\"na\":\"\"},\"actions\":{\"text\":\"Actions\\/Recommendation\",\"yes\":\"\",\"no\":\"Forklifts (retrac) drivers should maintain a safe distance from other employees (when inserting \\/ removing pallets, the radius of the mast height including the load)\",\"na\":\"\"},\"action_category\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"Forklift\",\"na\":\"\"},\"ua_uc\":{\"text\":\"Action Category\",\"yes\":\"\",\"no\":\"UA-UC\",\"na\":\"\"},\"risk_severity\":{\"text\":\"UA-UC\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"risk_probability\":{\"text\":\"Risk Severity\",\"yes\":\"\",\"no\":\"High\",\"na\":\"\"},\"color_code\":{\"text\":\"Risk Probability\",\"yes\":\"\",\"no\":\"Red\",\"na\":\"\"},\"cost_type\":{\"text\":\"Color Code\",\"yes\":\"\",\"no\":\"Operatiol Action\",\"na\":\"\"},\"combined_risk_rating\":{\"text\":\"Cost Type\",\"yes\":\"\",\"no\":\"48\",\"na\":\"\"}}', '', '', 1, '2026-04-22 00:41:46', '2026-04-22 00:41:46'),
