(33, 1, 2, '', 'QHSE and Sustainability', 'QHSE and Sustainability', 'MHE Inspection & maintenance', '<b>Target: 100% compliance\r\nRecords to be produced during audit (AMC, PPM records)</b>', 2, 'NO', 6, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(34, 1, 2, '', 'QHSE and Sustainability', 'QHSE and Sustainability', 'Weekly Safety Training / Awareness about Safety Fundamental', '<b>Target: 100% Adherence</b> \r\nWeekly Training records of last 3 month : Attache records File.\r\nSingle Week Missed record the score will be considered as Zero.', 2, 'NO', 7, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(35, 1, 2, '', 'KPIs', 'KPIs', '% of KPIs Target achieved', '<b>KPI adherence as per corporate guidelines for the months (KPI adherence % = 100%)</b>\r\nTarget Vs Adhered -Status', 5, 'NO', 8, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(36, 1, 2, '', 'KPIs', 'KPIs', '% of KPIs Target achieved', '<b>Agreement Target achieved for all KPI\'s For the last Quarter  (KPI Achievement % > 95%)</b>\r\nTarget Vs Achieved-Status of last 3 months', 5, 'NO', 9, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(37, 1, 2, '', 'KPIs', 'KPIs', '% of KPIs Target achieved', '<b>RCA for the Not achieved KPI and Action tracker</b>', 5, 'NO', 10, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(38, 1, 2, '', 'Inventory', 'Inventory', 'Cycle count Adherence', '<b>Target: >=100% for last quarter or consistently last three month</b>\r\nRecords of daily cycle count adherence for last 3 month', 5, 'NO', 11, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(39, 1, 2, '', 'Inventory', 'Inventory', 'Inventory Accuracy', '<b>Target: Inventory variance shall be within allowable shrinkage as per agreement</b>\r\nInventory variance in quantity and value (last 3 months )\r\nReconciliation status: IRA- ?? , IVA- ??\r\nStock Variance value : Is variance within the shrinkage limit?', 5, 'NO', 12, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(40, 1, 2, '', 'Inventory', 'Inventory', 'Inventory Accuracy', '<b>Location Accuracy for sample 50 locations (Target - 96% accuracy)</b>', 5, 'NO', 13, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(41, 1, 2, '', 'Inventory', 'Inventory', 'SAP / Client ERP / FM WMS reconciliation', '<b>Target: 100% Match for consistently last three  month</b>\r\nRecords of SAP vs WMS Match for the last 3 month. Check record for Stock Synchro\r\nRCA shall be available along with action tracker', 5, 'NO', 14, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(42, 1, 2, '', 'Continuous improvement', 'Continuous improvement', 'Productivity Adherence as per solution', '<b>Target: >=95% For the (YTD Produtcivty to be considered)</b>\r\nRecord of solution productivity vs actual productivity for all key activity, Solution Productivity: , Actual productivity:', 5, 'NO', 15, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(43, 1, 2, '', 'Continuous improvement', 'Continuous improvement', 'KAIZEN per person', '<b>Target: One Kaizen Per FM employee / Year (if Monthly target is achieved)</b>\r\nTotal no of kaizen Implemented : \r\nTotal no of employee on FM Role :', 5, 'NO', 16, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(44, 1, 2, '', 'Standardisation / Basics', 'Standardisation / Basics', 'SQDCIEP Board management (L1/L2 meeting)', '<b>Target: 100% Adherence</b>  for consistently for last three month\r\nRecord of SQDC board for the last 3 Months and open actions status need to be updated till the audit date. \r\nAttendance records of SQDC meeting', 2.5, 'NO', 17, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(45, 1, 2, '', 'Standardisation / Basics', 'Standardisation / Basics', '5S Adherence, Gemba walk (atleast once a week by WM) and Audit', '<b>Target: 100% Adherence</b> \r\n5\'s audit record for 6 months and actions implemented.  \r\nWeekly Gemba walk records & action tracker\r\nPhysical conditions indicate 5\'s adherence at the time of the audit', 2.5, 'NO', 18, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(46, 1, 2, '', 'Standardisation / Basics', 'Standardisation / Basics', 'SOP /WI Availability and Adherence', '<b>Target: Availability and 100% Adherence</b> \r\n100% availability of work instruction and SOP', 2.5, 'NO', 19, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
(47, 1, 2, '', 'Standardisation / Basics', 'Standardisation / Basics', 'Weekly Operations Training', '<b>Target: 100% Adherence</b> \r\nWeekly Training records of last 6 month \r\nSingle Week Missed record the score will be considered as Zero.', 2.5, 'NO', 20, 0, 0, '2026-09-24 09:25:37', '0000-00-00 00:00:00', '', '', NULL, NULL, NULL, NULL),
