(542, 2, 4514, 3, 'Client Leased', 'External Warehouse', 'S.1', 'Review of visitor management', 'Are necessary PPE\'s like high visibility jacket being provided to all external partners/visitors while entering in the premises ?', '', 'NC', '', '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-09-23 16:14:01', '2026-09-23 16:14:01'),
(543, 2, 4515, 3, 'Client Leased', 'External Warehouse', 'S.2', 'Review of visitor management', 'Is there no/nil observation of unsafe behaviour among visitors?', '', 'NC', '', '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-09-23 16:14:01', '2026-09-23 16:14:01'),
(544, 2, 4516, 3, 'Client Leased', 'External Warehouse', 'S.3', 'Review of visitor management', 'Are visitors been given safety briefing at the time of visiting the facility ?', '', 'NC', '', '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-09-23 16:14:01', '2026-09-23 16:14:01'),
(545, 2, 4517, 3, 'Client Leased', 'External Warehouse', 'S.4', 'Review of visitor management', 'Do people visiting the storage / copacking / comanufacturing area move around the warehouse in the presence of an FM employee?', '', 'NC', '', '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-09-23 16:14:01', '2026-09-23 16:14:01'),
(546, 2, 4518, 3, 'Client Leased', 'External Warehouse', 'T', 'Review of Copacking Safety', 'Review of Copacking Safety', '', '', '', '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, '2026-09-23 16:14:01', '2026-09-23 16:14:01'),
(547, 2, 4519, 3, 'Client Leased', 'External Warehouse', 'T.1', 'Review of Copacking Safety', 'Are all conveyor / production line collaborators working with no loose clothes, no accessories (jewels) and do they tie back their hair ?', '', 'NC', '', '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-09-23 16:14:01', '2026-09-23 16:14:01'),
(548, 2, 4520, 3, 'Client Leased', 'External Warehouse', 'T.2', 'Review of Copacking Safety', 'Are the conveyor / collaborators operating the production lines and using any mechanical equipment properly trained (check for training records) ?', '', 'NC', '', '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-09-23 16:14:01', '2026-09-23 16:14:01'),
(549, 2, 4521, 3, 'Client Leased', 'External Warehouse', 'T.3', 'Review of Copacking Safety', 'Are warning signages respected (Check for the accident records due to non-respect) ?', '', 'NC', '', '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-09-23 16:14:01', '2026-09-23 16:14:01'),
(550, 2, 4522, 3, 'Client Leased', 'External Warehouse', 'T.4', 'Review of Copacking Safety', 'Are only hand pallet trucks or electric pallet stackers used in the conveyor / production areas (no forklifts, no reach trucks) ?', '', 'NC', '', '', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-09-23 16:14:01', '2026-09-23 16:14:01'),
